#!/usr/bin/env python3
"""Writes outputs/g2a_act_corrections/protocol_freeze.json BEFORE any G2a outcome exists (refuses to overwrite).  Run (ACT venv): python eval/g2a_freeze.py"""
import json, sys, time, hashlib
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent; sys.path.insert(0, str(ROOT / "eval")); D = ROOT / "outputs/g2a_act_corrections"; F = D / "protocol_freeze.json"
if F.exists(): sys.exit("freeze exists")
if (D / "results").exists() and any((D / "results").glob("g2a_results.json")): sys.exit("results exist before freeze")
sh = lambda p: hashlib.sha256((ROOT / p).read_bytes()).hexdigest()
import closed_loop_pilot as P, g2a_act_corrections as G
rep = json.loads((D / "integration_report.json").read_text()); assert rep["verdict"] == "PASS" and rep["n_gates"] == 12
for f, h in rep["code_sha256"].items(): assert sh(f) == h, f
poses, mind = G.sample_poses(); ck = P.CK[G.POLICY]
files = ["eval/g2a_act_corrections.py", "eval/test_g2a_act_corrections.py", "eval/g2a_analysis.py", "eval/g2a_freeze.py", "eval/branching_replay.py", "eval/branching_metrics.py", "eval/closed_loop_pilot.py", "eval/decision_utility_lib.py", "data/indep_manifest.py", "policies/baseline.py", "sim/ik.py", "sim/lab_env.py", "sim/lab_scene.py", "control/safety_limits.py", "control/action_adapter.py",
         "outputs/g1_grasp/protocol_freeze.json", "outputs/indep/manifest.json", "outputs/g2a_act_corrections/integration_report.json", f"outputs/checkpoints/{ck}/last/model.safetensors", f"outputs/checkpoints/{ck}/last/config.json", f"outputs/checkpoints/{ck}/last/norm_contract.json", f"outputs/checkpoints/{ck}/last/policy_preprocessor_step_3_normalizer_processor.safetensors", f"outputs/checkpoints/{ck}/last/policy_postprocessor_step_0_unnormalizer_processor.safetensors"]
fz = dict(name="G2a ACT-anchored grasp corrections - protocol freeze", frozen_at=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), g2a_outcomes_exist_at_freeze=False, label="DEVELOPMENT; ORACLE-ASSISTED causal intervention (box pose used for the geometric reference); simulation only; no training; not a deployable policy; short-horizon grasp success only",
          poses=poses, poses_sha256=hashlib.sha256(json.dumps(poses, sort_keys=True).encode()).hexdigest(), pose_rng=[20261103, 9201], min_chebyshev_to_any_previously_used_state=mind, pose_selection="48 poses drawn without looking at any model/outcome: 32 'hard' (x 0.34-0.38) + 16 'mid' (0.38-0.47); y 0.07-0.13; yaw -0.20..0.20; rejected within Chebyshev 0.003 of every previously used state (xsweep/Stage 1/branching/G1/indep/wm datasets); no seeds 31-33; development-only afterwards",
          policy=dict(checkpoint=POLICY if (POLICY := G.POLICY) else None, path=f"outputs/checkpoints/{ck}/last", execution="full 20-step chunks, open loop within a chunk; clip->slew sequential from the last executed command; absolute 16-D actuator targets"), decision_state="start of the 20-step ACT chunk at control step t=40 (one per pose); APPLICABLE iff the executed gripper target at t=39 is open (>= 0.040 m) and the raw chunk contains a close command (< 0.040 m); else NOT_APPLICABLE (no branches)",
          horizon=dict(T_DEC=G.T_DEC, T_END=G.T_END, note="ACT queried normally at t=60 and t=80 after the corrected chunk; branches end at t=100 (61 rows)"),
          candidates=G.CANDS, constants=dict(clip_pooled_error_p5_p95=G.CLIP, ramp_early_steps=G.RAMP_EARLY, ramp_late_steps=G.RAMP_LATE, delay_steps=G.DELAY_STEPS, fixed_depth_m=G.FIXED_DEPTH), reference="oracle-cancel: correction = - clip(error), error = ACT-commanded TCP (FK of the raw targets after removing the gravity-comp offset) at its own close step vs the expert grasp point (box centre + 0.01 m along the box finger axis) in the box frame at the INITIAL box pose; yaw error = hand yaw (R R0^T) - box yaw",
          correction_operator="raw chunk -> remove gravity-comp offset -> FK -> TCP shift in the box frame (depth f, lateral n) / rotation about world z (yaw) weighted by a ramp w(s) (early: min(1,(s+1)/6) from the chunk start; late: 0->1 over 4 steps ending at the ACT close step) -> IK (tol 0.5 mm) -> gravity-comp -> ctrlrange clip -> slew; steps with w=0 and c0 are bit-exact ACT; the joint-space offset at the last corrected step persists on the following ACT chunks; c4 shifts the gripper channel (close event) by 8 steps; no other channel is modified",
          validity="IK residual < 2 mm and < 0.03 rad at every corrected step; executed chain legal and finite; robot-obstacle (desk/tray/room) penetration <= 2 mm; shallower grazes only recorded",
          outcome=dict(GRASP_SUCCESS="t_close = first executed left-gripper target < 0.040 m (>= t=40); closure: >= 2 finger-box contact points at t_close+14; t_lift = first row with box rise >= 0.05 m above the initial height; hold window = rows t_lift+8 .. t_lift+16 (must fit in the horizon else 'late_lift' = failure): rise >= 0.05 m, box-TCP distance < 0.06 m, slip (max deviation of the box-TCP vector from its window mean) <= 0.01 m, and no drop (rise < 0.02 m after reaching 0.05 m) until t=100",
                       reasons="success | not_closed | not_lifted | late_lift | dropped | slipped", palm="hand-collision force > 0.01 N at any row t=40..100", NOT_EVALUABLE="invalid candidates; end-to-end carry/place (horizon < 105)"),
          statistics=dict(unit="pose", bootstrap="10000 resamples of poses, seed 0, 95 % percentile CI; candidates of one pose never treated as independent", primary="oracle best-of-9 headroom (binary) vs nominal ACT and PRIMARY paired comparison c1 (depth-only oracle-cancel) - c0 with improved/harmed/unchanged counts", secondary="all other candidates vs nominal, timing (c1 vs c2), random (expected over valid candidates), non-oracle heuristic c5 (fixed shallower 2 cm), strata, palm/contact/slip"),
          stop_rules=["candidate validity < 80 % -> STOP", "critical physics/action/IK/snapshot gate failure -> STOP", "> 80 % of evaluable states without oracle binary headroom -> STOP", "all nominal ACT grasps succeed -> NO_HEADROOM (reported, no continuous proxy added afterwards)", "CPU cap 0.25 process CPU-h for all of G2a -> PARTIAL, no extension"], compute=dict(cap_total_s=G.CAP_TOTAL_S, ledger_used_at_freeze_s=G.ledger_used()), files_sha256={f: sh(f) for f in files})
P.atomic_json(F, fz); print(hashlib.sha256(F.read_bytes()).hexdigest(), fz["frozen_at"], len(files), "files; ledger", fz["compute"]["ledger_used_at_freeze_s"], "poses", len(poses), "min dist", mind)
